class EmailLoginFlow extends StatefulWidget{
  const EmailLoginFlow({super.key,required this.service});final PollarService service;
  @override State<EmailLoginFlow> createState()=>_EmailLoginFlowState();
}
class _EmailLoginFlowState extends State<EmailLoginFlow>{
  final email=TextEditingController(),code=TextEditingController();int step=0;String? error;bool submitting=false;
  @override void initState(){super.initState();widget.service.addListener(changed);}
  void changed(){if(!mounted)return;final p=widget.service;if(p.authenticated){WidgetsBinding.instance.addPostFrameCallback((_){if(mounted)Navigator.pop(context);});return;}if(p.step=='entering_code'&&step==0)setState(()=>step=1);else setState((){});}
  @override void dispose(){widget.service.removeListener(changed);if(!widget.service.authenticated)unawaited(widget.service.engine.call('pollarCancel').catchError((_)=>null));email.dispose();code.dispose();super.dispose();}
  Future<void> next()async{final p=widget.service;if(step==0&&!RegExp(r'^[^\s@]+@[^\s@]+\.[^\s@]+$').hasMatch(email.text.trim())){setState(()=>error='Escribe un correo electrónico válido.');return;}if(step==1&&code.text.trim().isEmpty){setState(()=>error='Escribe el código que recibiste.');return;}setState((){error=null;submitting=true;});try{await p.action(step==0?'pollarEmailStart':'pollarVerify',step==0?{'email':email.text.trim()}:{'code':code.text.trim()});}catch(e){if(mounted)setState(()=>error=PollarService.message(e));}finally{if(mounted)setState(()=>submitting=false);}}
  @override Widget build(BuildContext context){final p=widget.service,waiting=submitting||p.busy||['creating_session','sending_email','verifying_email_code','authenticating'].contains(p.step);return FlowPanel(title:'Acceso con correo',icon:Icons.alternate_email_rounded,step:step,steps:2,heading:step==0?'¿Cuál es tu correo?':'Revisa tu correo',subtitle:step==0?'Te enviaremos un código para entrar o recuperar tu cuenta.':'Introduce el código enviado a ${email.text.trim()}.',busy:waiting,error:error??p.state['message'] as String?,nextLabel:step==0?'Enviar código':'Verificar código',onClose:()async{await walletAction(context,()=>p.action('pollarCancel'));if(context.mounted)Navigator.pop(context);},onBack:(){p.action('pollarCancel');setState(()=>step=0);},onNext:next,child:Column(crossAxisAlignment:CrossAxisAlignment.stretch,spacing:18,children:[if(step==0)TextField(controller:email,keyboardType:TextInputType.emailAddress,autofillHints:const [AutofillHints.email],decoration:InputDecoration(labelText:t('Correo electrónico'),prefixIcon:const Icon(Icons.alternate_email_rounded)))else ...[TextField(controller:code,keyboardType:TextInputType.number,autofillHints:const [AutofillHints.oneTimeCode],style:h(30),textAlign:TextAlign.center,decoration:InputDecoration(labelText:t('Código de verificación'))),TextButton(onPressed:waiting?null:()=>walletAction(context,()=>p.action('pollarResend',{'email':email.text.trim()})),child:const Text('Reenviar código'))]]));}
}

class RecoveryFlow extends StatefulWidget{
  const RecoveryFlow({super.key,required this.service,required this.recover});final PollarService service;final bool recover;
  @override State<RecoveryFlow> createState()=>_RecoveryFlowState();
}
class _RecoveryFlowState extends State<RecoveryFlow>{
  final email=TextEditingController(),code=TextEditingController(),device=TextEditingController();int step=0;String method='email';bool busy=false;String? error,enrollment;
  @override void dispose(){email.dispose();code.dispose();device.dispose();super.dispose();}
  Future<void> next()async{
    setState(()=>error=null);final p=widget.service;
    if(step==0){setState(()=>step=1);return;}
    if(method=='device'){setState(()=>busy=true);try{if(widget.recover){final r=await p.action('pollarEnroll') as Map;setState(()=>enrollment=r['id'] as String);await Clipboard.setData(ClipboardData(text:enrollment!));}else{if(device.text.trim().isEmpty)throw const FormatException('Escribe el identificador de la solicitud.');if(!await confirm(context,'Autorizar otro dispositivo','Solo aprueba una solicitud que acabas de iniciar en un dispositivo tuyo. Tendrá acceso a tu wallet.'))return;await p.action('pollarApproveDevice',{'id':device.text.trim()});if(context.mounted)Navigator.pop(context);}}catch(e){if(mounted)setState(()=>error=PollarService.message(e));}finally{if(mounted)setState(()=>busy=false);}return;}
    if(step==1&&!widget.recover&&!RegExp(r'^[^\s@]+@[^\s@]+\.[^\s@]+$').hasMatch(email.text.trim())){setState(()=>error='Correo no válido.');return;}
    setState(()=>busy=true);
    try{if(step==1){await p.action(widget.recover?'pollarDeviceRecoverStart':'pollarRecoveryStart',{'email':email.text.trim()});if(mounted)setState(()=>step=2);}else{await p.action(widget.recover?'pollarDeviceRecoverConfirm':'pollarRecoveryConfirm',{'code':code.text.trim()});if(context.mounted)Navigator.pop(context);}}
    catch(e){if(mounted)setState(()=>error=PollarService.message(e));}finally{if(mounted)setState(()=>busy=false);}
  }
  @override Widget build(BuildContext context)=>FlowPanel(title:widget.recover?'Recuperar mi billetera':'Proteger mi billetera',icon:Icons.shield_outlined,color:C.lavender,step:step,steps:method=='device'?2:3,heading:step==0?'Tu acceso, bajo tu control':method=='device'?(widget.recover?'Solicita acceso a este teléfono':'Autoriza tu otro dispositivo'):step==1?(widget.recover?'Usa tu correo de recuperación':'Elige un correo de recuperación'):'Confirma tu protección',subtitle:step==0?'Elige cómo proteger o recuperar tu billetera.':method=='device'?'La solicitud debe iniciarse desde uno de tus dispositivos.':step==1?'Necesitarás poder acceder a este correo aunque pierdas el teléfono.':'Escribe el código enviado a tu correo.',nextLabel:step==0?'Siguiente':method=='device'?(widget.recover?'Solicitar acceso':'Autorizar dispositivo'):step==1?'Enviar código':widget.recover?'Recuperar acceso':'Confirmar protección',busy:busy,error:error,onClose:()=>Navigator.pop(context),onBack:()=>setState(()=>step--),onNext:next,child:step==0?Column(children:[FlowChoice(title:'Correo de recuperación',subtitle:'Verificación mediante un código',icon:Icons.alternate_email_rounded,color:C.lavender,selected:method=='email',onTap:()=>setState(()=>method='email')),FlowChoice(title:'Otro dispositivo',subtitle:widget.recover?'Pide autorización desde un equipo con acceso':'Autoriza una solicitud de tu otro equipo',icon:Icons.phonelink_lock_outlined,color:C.lavender,selected:method=='device',onTap:()=>setState(()=>method='device'))]):method=='device'?Column(crossAxisAlignment:CrossAxisAlignment.stretch,spacing:16,children:[if(widget.recover)...[const Notice('Pulsa “Solicitar acceso”. Luego aprueba el identificador desde tu otro dispositivo.'),if(enrollment!=null)SelectableText('Identificador copiado:\n$enrollment',style:body(13))]else TextField(controller:device,autocorrect:false,decoration:InputDecoration(labelText:t('Identificador de la solicitud')))]):step==1?(widget.recover?const Notice('Te enviaremos un código al correo de recuperación que ya verificaste para esta billetera.'):TextField(controller:email,keyboardType:TextInputType.emailAddress,decoration:InputDecoration(labelText:t('Correo electrónico')))):TextField(controller:code,keyboardType:TextInputType.number,autofillHints:const [AutofillHints.oneTimeCode],style:h(30),textAlign:TextAlign.center,decoration:InputDecoration(labelText:t('Código de verificación'))));
